#!/usr/bin/env bash
set -Eeuo pipefail
umask 077
test "$(id -u)" = 0 || { echo '请使用 sudo bash。' >&2; exit 1; }
if ! command -v node >/dev/null; then
 set +eu
 export NVM_DIR=/root/.nvm
 [ ! -s "$NVM_DIR/nvm.sh" ] || . "$NVM_DIR/nvm.sh"
 set -Eeuo pipefail
fi
for tool in node curl flock; do command -v "$tool" >/dev/null; done
exec 9>/root/.note-security-install.lock
flock -n 9
live=/root/telegram-notes/public/index.html
test -f "$live"; test "$(readlink -f "$live")" = "$live"
stage=$(mktemp -d /tmp/note-spoken-XXXXXXXX); chmod 700 "$stage"
base64 -d > "$stage/patch.cjs" <<'NOTE_SPOKEN_ASSET'

NOTE_SPOKEN_ASSET
base64 -d > "$stage/note-crypto.js" <<'NOTE_SPOKEN_ASSET'

NOTE_SPOKEN_ASSET
base64 -d > "$stage/security-client.js" <<'NOTE_SPOKEN_ASSET'

NOTE_SPOKEN_ASSET
node "$stage/patch.cjs" "$live" "$stage/index.html" "$stage"
backup=$(mktemp -d /root/note-spoken-code-backup-XXXXXXXX); chmod 700 "$backup"
cp -a "$live" "$backup/index.html"
rollback(){ trap - ERR INT TERM; cp -a "$backup/index.html" "$live"; echo "恢复原页面：$backup" >&2; exit 1; }
trap rollback ERR INT TERM
cp "$stage/index.html" "$live.note-spoken-next"; chmod 644 "$live.note-spoken-next"; mv -f "$live.note-spoken-next" "$live"
curl --noproxy '*' -fsS --retry 3 --max-time 15 http://127.0.0.1:3000/ -o "$stage/served.html"
cmp "$stage/index.html" "$stage/served.html"
trap - ERR INT TERM
echo "NOTE_SPOKEN_UPDATE_SUCCESS backup=$backup"
echo '便签口述口令页面已上线。'
